cat > zz_heldout_test.go <<'EOF'
package notify

import "testing"

func TestHeldoutSize(t *testing.T) {
	if got := Size(Message{To: "a@x.io", Body: "h\u00e9"}); got != 3 {
		t.Errorf("Size = %d, want 3 bytes", got)
	}
	if got := Size(Message{}); got != 0 {
		t.Errorf("Size(empty) = %d, want 0", got)
	}
}
EOF
go test -count=1 -run Heldout ./...; rc=$?; rm -f zz_heldout_test.go; exit $rc

