package notify

import "testing"

func TestHeldoutDedupeIgnoresCase(t *testing.T) {
	got := Dedupe([]Message{{To: "Ann@x.io", Body: "1"}, {To: "bob@x.io", Body: "2"}, {To: "ann@X.io", Body: "3"}})
	if len(got) != 2 || got[0].Body != "1" || got[1].Body != "2" {
		t.Errorf("Dedupe = %v, want the messages with bodies 1 and 2", got)
	}
}
EOF
go test -count=1 -run Heldout ./...; rc=$?; rm -f zz_heldout_test.go; exit $rc
